package special

import (
	"math"

	"github.com/go-numerics/special/dd"
)

// lgammaOctPiece is one piece of lgammaOctPieces (zz_lgammaOct_coeffs.go,
// generated by testdata/gen/fitgo lgamma-oct): for x in a piece of 1/64 of an
// octave, s = x - c exact,
//
//	log Γ(x) = (lh + ll) + (a1 + a1l) s + s² T(s),  T = a2 + a3 s + ... + a7 s^5,
//
// stored r[0] = a7 ... r[5] = a2 (Horner order).
type lgammaOctPiece struct {
	c, lh, ll float64
	a1, a1l   float64
	r         [6]float64
}

// lgammaOct returns log Γ(x) for 10 <= x < 1024 from the table, rounded once:
// the constant and the slope term (which reaches 54) as double-doubles, the
// rest (below 0.03) in float64, rounded at 2^-53 of itself, that is below
// 2^-9 ulp of the result (log Γ(10) = 12.8, whose ulp is 2^-49).
func lgammaOct(x float64) float64 {
	b := math.Float64bits(x)
	p := &lgammaOctPieces[(int(b>>52)-1023-3)<<6|int(b>>46&63)]
	s := x - p.c // exact: both are multiples of ulp(x) and |s| < x/128
	t := p.r[0]
	t = math.FMA(t, s, p.r[1])
	t = math.FMA(t, s, p.r[2])
	t = math.FMA(t, s, p.r[3])
	t = math.FMA(t, s, p.r[4])
	t = math.FMA(t, s, p.r[5])
	q := float64(float64(s*s) * t)
	ph, pe := dd.TwoProd(s, p.a1)
	pl := math.FMA(s, p.a1l, pe)
	sh, se := dd.TwoSum(p.lh, ph)
	return sh + (se + ((p.ll + pl) + q))
}
